    ["2028-07-18", L3("Deadline for Vietnam's follow-up report to the UN Human Rights Committee on a national human rights institution, the death penalty and pretrial detention.",
                      "Date limite du rapport de suivi du Viêt Nam au Comité des droits de l'homme de l'ONU sur une institution nationale des droits de l'homme, la peine de mort et la détention provisoire.",
                      "Plazo del informe de seguimiento de Vietnam al Comité de Derechos Humanos de la ONU sobre una institución nacional de derechos humanos, la pena de muerte y la prisión preventiva."), U.ccpr25],
    ["2031-01-20", L3("2031 (date not set): 15th Party Congress and election of a new National Assembly at the end of the 2026-2031 term; the date shown is an estimate.",
                      "2031 (date non fixée) : 15e Congrès du Parti et élection d'une nouvelle Assemblée nationale à la fin du mandat 2026-2031 ; la date indiquée est une estimation.",
                      "2031 (sin fecha): XV Congreso del Partido y elección de una nueva Asamblea Nacional al final del mandato 2026-2031; la fecha indicada es una estimación."), U.pm]
